def is_balanced(s):
    stack = []
    mapping = {')': '(', ']': '[', '}': '{'}
    for c in s:
        if c in mapping.values():
            stack.append(c)
        elif c in mapping.keys():
            if not stack or stack.pop() != mapping[c]:
                return False
    return len(stack) == 0
```

